package dev.pocketengine.features.teams;

import java.util.concurrent.TimeUnit;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

/** Actual original SQLite/book/coordinator files survive JVMs. Metadata only locates this synthetic seed. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=TeamBudgetPersistentApplication.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
@ConscryptMode(ConscryptMode.Mode.OFF)
public final class TeamResearchLateColdNativeJourneyTest {
    @Test public void seedAtSixteenActuallyReadPagesAndExplicitlyReviewColdReconstructionBudget()throws Exception {
        assertFalse(Boolean.getBoolean("a25.researchLateContinue"));try(var f=new TeamResearchAgentNativeJourneyTest.Fixture(true,false,false,false,true,false,true)){
            f.waitIdle();var page=f.research.openBudget(f.coordinator,f.run);page.setForeground(true);var review=page.review(32,24);page.approve(review,review.view().getString("digest"));page.close();f.resumeNative();assertTrue("actual16 pages must precede the cold boundary",f.compactMainEntered.await(170,TimeUnit.SECONDS));assertEquals(16,f.completedTool("team_read_source"));assertEquals(0,f.completedTool("memory_raw_query"));JSONObject view=f.coordinator.get(f.run),member=view.getJSONArray("members").getJSONObject(0);f.coordinator.reviewedControl("pause",new JSONObject().put("runId",f.run).put("memberId","a").put("expectedRevision",view.getLong("revision")).put("expectedGeneration",view.getInt("generation")).put("expectedMemberGeneration",member.getInt("generation")),f.model,f.materials,null);f.releaseCompactMain.countDown();f.waitIdle();assertFalse(f.tasks.hasUnresolved(f.child().getString("id")));JSONObject old=f.tasks.teamBudgetSnapshot(f.run);int http=f.http.get();page=f.research.openBudget(f.coordinator,f.run);page.setForeground(true);review=page.review(48,24);page.approve(review,review.view().getString("digest"));page.close();JSONObject saved=f.tasks.teamBudgetSnapshot(f.run);assertEquals(http,f.http.get());assertEquals(old.getInt("modelRequestsReservedOrUsed"),saved.getInt("modelRequestsReservedOrUsed"));assertEquals(old.getInt("toolOperationsReservedOrUsed"),saved.getInt("toolOperationsReservedOrUsed"));assertEquals(48,saved.getInt("modelRequestLimit"));assertEquals("paused",f.coordinator.get(f.run).getString("status"));f.persistLateState();
        }
    }
    @Test public void coldRebuildsHugeRawInCurrentNativeSummaryChunksBeforeAnyMainAndNeverRepeatsReadPages()throws Exception {
        assertTrue(Boolean.getBoolean("a25.researchLateContinue"));try(var f=new TeamResearchAgentNativeJourneyTest.Fixture(true,false,false,false,true,false,true)){
            JSONObject before=f.child(),oldScope=f.tasks.teamMemberMaterialScope(f.run,"a"),oldPool=f.tasks.teamBudgetSnapshot(f.run);int beforeHttp=f.http.get();assertTrue("original 10-minute ticket really expired; never edit it",oldScope.getLong("expiresAt")<=System.currentTimeMillis());
            TeamMemberEvidenceHost.Page materials=f.materials.open(f.coordinator,f.run,"a");materials.setForeground(true);var review=materials.reviewRenewal();JSONObject shown=review.view();assertEquals("renew_identical_materials",shown.getString("reviewMode"));assertFalse("review label must not recursively copy read evidence bodies",shown.getJSONObject("member").has("evidence"));assertFalse(shown.getJSONObject("member").has("roundStates"));assertTrue("eight exact source spans fit without member audit recursion",shown.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length<16384);assertEquals(before.getString("id"),shown.getJSONArray("researchTasks").getJSONObject(0).getString("taskId"));JSONObject freshScope=materials.approve(review,shown.getString("digest"));assertEquals(oldScope.getLong("revision")+1,freshScope.getLong("revision"));assertTrue(freshScope.getLong("expiresAt")>System.currentTimeMillis());assertEquals(beforeHttp,f.http.get());assertEquals(oldPool.toString(),f.tasks.teamBudgetSnapshot(f.run).toString());JSONObject still=f.child();assertEquals(before.getString("id"),still.getString("id"));assertEquals(before.getString("runId"),still.getString("runId"));assertEquals(before.getInt("coordinatorEpoch"),still.getInt("coordinatorEpoch"));assertEquals(oldScope.toString(),still.getJSONObject("teamResearch").getJSONArray("materialScopeHistory").getJSONObject(0).toString());assertEquals(before.getJSONArray("teamResearchAttemptHistory").toString(),still.getJSONArray("teamResearchAttemptHistory").toString());f.trace("native-same-material-renewal",new JSONObject().put("oldScope",oldScope).put("approvedScope",freshScope).put("childId",still.getString("id")).put("poolBefore",oldPool).put("poolAfter",f.tasks.teamBudgetSnapshot(f.run)).put("httpBefore",beforeHttp).put("httpAfter",f.http.get()).put("oldRunUntouched",true));try{materials.approve(review,shown.getString("digest"));fail("old native review must be single use");}catch(SecurityException expected){}materials.close();
            int summaries=f.compactSummaries.get();f.resumeNative();f.waitIdle();JSONObject current=f.child(),pool=f.tasks.teamBudgetSnapshot(f.run);f.trace("late-cold-child",new JSONObject().put("id",current.getString("id")).put("status",current.optString("status")).put("summary",current.optString("summary")).put("evidence",current.optJSONObject("evidence")));f.trace("late-cold-budget",pool);assertEquals("completed",f.coordinator.get(f.run).getString("status"));assertEquals("completed",current.getString("status"));assertEquals(before.getString("id"),current.getString("id"));assertEquals(before.getInt("coordinatorEpoch")+1,current.getInt("coordinatorEpoch"));assertEquals(16,f.completedTool("team_read_source"));assertEquals(1,f.completedTool("memory_raw_query"));assertEquals(1,f.completedTool("memory_raw_read"));assertTrue("cold huge raw needs multiple newly metered current-native summaries",f.compactSummaries.get()>=summaries+2);assertEquals(f.http.get(),pool.getInt("modelRequestsReservedOrUsed"));assertEquals(18,pool.getInt("toolOperationsReservedOrUsed"));assertEquals(48,pool.getInt("modelRequestLimit"));assertFalse(f.tasks.hasUnresolved(current.getString("id")));assertFalse(current.getJSONObject("evidence").getBoolean("businessVerified"));
        }
    }
}
